xs=[-100,-80,-60,-40,-20,0,20,40,60,80,100]
fs=[4,8,13,23,34,36,32,24,12,8,0]
def fval(x):
    if x<=xs[0] or x>=xs[-1]: return 0.0
    for i in range(len(xs)-1):
        if xs[i] <= x <= xs[i+1]:
            t=(x-xs[i])/(xs[i+1]-xs[i]); return fs[i]*(1-t)+fs[i+1]*t
    return 0.0
def sums(lines, ys):
    return [sum(fval(y-l) for l in lines) for y in ys]
def eval(label, lines):
    ys=[i*2.5 for i in range(0,181)] # 0..450 step 2.5
    vals=sums(lines,ys)
    qy=[30,225,420]
    qv=sums(lines,qy)
    print(label, 'n',len(lines),'lines',lines)
    print('min/max panel',round(min(vals),1),round(max(vals),1),'QC',[round(v,1) for v in qv], 'edges', [round(v,1) for v in sums(lines,[0,450])])
for margin in [0,25,50]:
    for mode in ['inclusive','centered']:
        lo=-margin; hi=450+margin
        if mode=='inclusive':
            lines=[]
            y=lo
            while y<=hi+1e-9:
                lines.append(y); y+=50
        else:
            # center lines in region with pitch 50: first at lo + pitch/2, last within hi maybe <= hi-pitch/2
            lines=[]
            y=lo+25
            while y<=hi-25+1e-9:
                lines.append(y); y+=50
        eval(f'margin {margin} {mode}', lines)
